// Cross-language conformance: the JS implementation must reproduce the exact digests the
// Rust kernel produces. The vectors are generated by the Rust golden-vector tests and
// committed; CI runs this file against them.
//
// This is the C6 evidence in one sentence: an independent implementation verifies our
// receipts.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { digest, hashValueAction, saltFor } from '../lib/eip712.js';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const vectors = JSON.parse(
  readFileSync(join(ROOT, 'docs/golden-vectors/vectors.json'), 'utf8'),
);

const b = (hex) => new Uint8Array([...Buffer.from(String(hex).replace(/^0x/, ''), 'hex')]);
const h = (bytes) => Buffer.from(bytes).toString('hex');

for (const [i, v] of vectors.entries()) {
  test(`golden vector ${i}: the JS digest matches the Rust digest`, () => {
    const domain = { name: v.domain.name, version: v.domain.version, salt: b(v.domain.salt) };
    const receipt = {
      agentId: b(v.receipt.agentId),
      sessionId: b(v.receipt.sessionId),
      class: v.receipt.class,
      actionHash: b(v.receipt.actionHash),
      manifestHash: b(v.receipt.manifestHash),
      contextHash: b(v.receipt.contextHash),
      verdict: v.receipt.verdict,
      nonce: b(v.receipt.nonce),
      issuedMs: v.receipt.issuedMs,
      expiryMs: v.receipt.expiryMs,
    };
    assert.equal(h(digest(domain, receipt)), v.digest);
  });
}

test('the domain salt binds the chain id and the contract id', () => {
  const salt = saltFor('sandbox', 'vault.test.near');
  assert.equal(salt.length, 32);
  assert.notEqual(h(salt), h(saltFor('testnet', 'vault.test.near')));
  assert.notEqual(h(salt), h(saltFor('sandbox', 'other.test.near')));
});

test('a one-byte change to any receipt field changes the digest', () => {
  const v = vectors[0];
  const domain = { name: v.domain.name, version: v.domain.version, salt: b(v.domain.salt) };
  const base = {
    agentId: b(v.receipt.agentId),
    sessionId: b(v.receipt.sessionId),
    class: v.receipt.class,
    actionHash: b(v.receipt.actionHash),
    manifestHash: b(v.receipt.manifestHash),
    contextHash: b(v.receipt.contextHash),
    verdict: v.receipt.verdict,
    nonce: b(v.receipt.nonce),
    issuedMs: v.receipt.issuedMs,
    expiryMs: v.receipt.expiryMs,
  };
  const original = h(digest(domain, base));

  for (const field of ['agentId', 'sessionId', 'actionHash', 'manifestHash', 'contextHash', 'nonce']) {
    const tampered = { ...base, [field]: new Uint8Array(base[field]) };
    tampered[field][0] ^= 1;
    assert.notEqual(h(digest(domain, tampered)), original, `${field} must be bound`);
  }
  for (const field of ['class', 'verdict', 'issuedMs', 'expiryMs']) {
    const tampered = { ...base, [field]: base[field] + 1 };
    assert.notEqual(h(digest(domain, tampered)), original, `${field} must be bound`);
  }
});

test('the action hash binds the destination and the amount', () => {
  const action = {
    chain: 'sandbox',
    venue: 'venue-a',
    to: 'alice.test.near',
    asset: 'near',
    amount: '42',
    memoHash: new Uint8Array(32),
  };
  const original = h(hashValueAction(action));
  assert.notEqual(h(hashValueAction({ ...action, to: 'bob.test.near' })), original);
  assert.notEqual(h(hashValueAction({ ...action, amount: '43' })), original);
});
